const ELEMENT_PROP_KEYS = new Set(["theme","question","answerLead","answer","showLogo","stagger","intensity","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
